 if(g.boss.x<82||g.boss.x>278){g.boss.vx*=-1;g.boss.x=Math.max(82,Math.min(278,g.boss.x))}if(g.boss.y>400){g.boss.dashing=false;g.boss.vy=-320}if(g.boss.y<205){g.boss.y=205;g.boss.vy=Math.abs(g.boss.vy)}
