 const nx=dx/(Math.hypot(dx,dy)||1),ny=dy/(Math.hypot(dx,dy)||1),ret=g.dashActive>0?.97:cfg.bossRetention;e.vx=nx*Math.max(360,speed*ret);e.vy=ny*Math.max(360,speed*ret);g.boss.vx-=nx*(frontal?180:75);g.boss.vy-=ny*(frontal?160:55);g.boss.recoil=.13;
